const api = $('Webhook').first().json.body;
const hojas = $input.first().json;
const salida = (() => {
const SUFIJO = 'PRUEBAS';
const COLUMNAS = 11;
const FIJAS = 4;

if (!api || !Array.isArray(api.vehiculos) || !Array.isArray(api.dias) || api.dias.length !== 7) {
  throw new Error('La respuesta de la API no trae vehiculos y siete dias.');
}

const f = new Date(api.desde + 'T00:00:00Z');
const jueves = new Date(f);
jueves.setUTCDate(f.getUTCDate() + 3 - ((f.getUTCDay() + 6) % 7));
const primero = new Date(Date.UTC(jueves.getUTCFullYear(), 0, 4));
const semana = 1 + Math.round(((jueves - primero) / 86400000 - 3 + ((primero.getUTCDay() + 6) % 7)) / 7);
const anio2 = String(jueves.getUTCFullYear()).slice(-2);
const titulo = String(semana).padStart(2, '0') + '-' + anio2 + SUFIJO;

if (!titulo.endsWith(SUFIJO)) throw new Error('Solo se escribe en pestañas acabadas en ' + SUFIJO);

const existente = (hojas.sheets || []).map((s) => s.properties).find((p) => p.title === titulo);
const sheetId = existente ? existente.sheetId : 900000000 + semana * 100 + Number(anio2);

const texto = (v) => (v === null || v === undefined ? '' : String(v));
const celda = (v) => (typeof v === 'number' ? { userEnteredValue: { numberValue: v } } : { userEnteredValue: { stringValue: texto(v) } });

const cabecera = ['', 'REMOLQUE', 'PRECIO', 'CHOFER / TELF / MATRICULAS', ...api.dias.map((d) => d.dia_semana.toUpperCase() + ' ' + d.dia_mes)];
const filas = [cabecera];
const unidos = [];
const separadores = [];

api.vehiculos.forEach((v, i) => {
  const base = 1 + 3 * i;
  const conductores = v.conductores || [];
  const primerMovimiento = (v.movimientos || [])[0];
  const transportista = v.transportista || (primerMovimiento && primerMovimiento.transportista) || null;
  const empresaOTransportista = v.propio === true && v.empresa ? v.empresa.nombre : transportista ? transportista.abreviatura || transportista.nombre : '';
  const porFecha = {};
  (v.dias || []).forEach((d) => { porFecha[d.fecha] = d; });

  const fila1 = [
    v.matricula ? v.orden : '',
    v.remolque ? v.remolque.matricula : '',
    '',
    conductores.length ? v.matricula + ' // ' + (conductores[0].apodo || '') : v.matricula,
  ];
  const fila2 = ['', '', '', conductores.map((c) => c.codigo).join(' // ')];
  const fila3 = ['', empresaOTransportista, '', v.num_conductores > 0 ? v.num_conductores + 'CH' : ''];

  api.dias.forEach((dia) => {
    const d = porFecha[dia.fecha] || { paradas_texto: '', notas: [] };
    fila1.push(d.paradas_texto || '');
    fila2.push((d.notas || []).map((n) => n.texto || n.concepto || '').filter(Boolean).join(' / '));
    fila3.push('');
  });

  fila2[0] = v.remolque && v.remolque.tipo ? v.remolque.tipo.nombre || v.remolque.tipo.clave : '';

  filas.push(fila1, fila2, fila3);
  unidos.push({ sheetId, startRowIndex: base + 1, endRowIndex: base + 3, startColumnIndex: 0, endColumnIndex: 1 });
  separadores.push(base);
});

const totalFilas = filas.length;
const todo = { sheetId, startRowIndex: 0, endRowIndex: totalFilas, startColumnIndex: 0, endColumnIndex: COLUMNAS };
const gris = { red: 0.9, green: 0.9, blue: 0.9 };
const requests = [];

if (!existente) {
  requests.push({ addSheet: { properties: { sheetId, title: titulo, gridProperties: { rowCount: Math.max(totalFilas + 20, 100), columnCount: COLUMNAS } } } });
} else {
  requests.push({ unmergeCells: { range: { sheetId } } });
  requests.push({ updateCells: { range: { sheetId }, fields: 'userEnteredValue,userEnteredFormat' } });
}
requests.push({ updateSheetProperties: { properties: { sheetId, gridProperties: { frozenRowCount: 1, frozenColumnCount: FIJAS } }, fields: 'gridProperties.frozenRowCount,gridProperties.frozenColumnCount' } });
requests.push({ updateCells: { start: { sheetId, rowIndex: 0, columnIndex: 0 }, rows: filas.map((fila) => ({ values: fila.map(celda) })), fields: 'userEnteredValue' } });
requests.push({ repeatCell: { range: { ...todo, startRowIndex: 1 }, cell: { userEnteredFormat: { verticalAlignment: 'TOP', wrapStrategy: 'WRAP' } }, fields: 'userEnteredFormat.verticalAlignment,userEnteredFormat.wrapStrategy' } });
requests.push({ repeatCell: { range: { ...todo, endRowIndex: 1 }, cell: { userEnteredFormat: { backgroundColor: gris, horizontalAlignment: 'CENTER', verticalAlignment: 'MIDDLE', textFormat: { bold: true } } }, fields: 'userEnteredFormat.backgroundColor,userEnteredFormat.horizontalAlignment,userEnteredFormat.verticalAlignment,userEnteredFormat.textFormat.bold' } });
unidos.forEach((range) => requests.push({ mergeCells: { range, mergeType: 'MERGE_ALL' } }));
separadores.forEach((fila) => requests.push({ updateBorders: { range: { sheetId, startRowIndex: fila, endRowIndex: fila + 1, startColumnIndex: 0, endColumnIndex: COLUMNAS }, top: { style: 'SOLID', color: { red: 0.4, green: 0.4, blue: 0.4 } } } }));
[[0, 1, 60], [1, 2, 110], [2, 3, 70], [3, 4, 200], [4, 11, 160]].forEach(([ini, fin, px]) => requests.push({ updateDimensionProperties: { range: { sheetId, dimension: 'COLUMNS', startIndex: ini, endIndex: fin }, properties: { pixelSize: px }, fields: 'pixelSize' } }));

return {
  batch: { requests },
  pestana: { titulo, sheetId, existia: !!existente },
  resumen: { semana: api.desde + ' a ' + api.hasta, vehiculos: api.vehiculos.length, filas: totalFilas, peticiones: requests.length },
};
})();
return [{ json: salida }];
